// sm_120 and sm_121 read a warp's next k tile ahead, bit-equal (contract_exl3_grouped.zig); older SMs keep main's loop.
#if __CUDA_ARCH__ >= 1200
constexpr int GROUPED_LOAD = tf_exl3::AHEAD;
#else
constexpr int GROUPED_LOAD = tf_exl3::PLAIN;
#endif

extern "C" __global__ void tf_exl3_grouped_0(tf_exl3::GroupedArgs a) {  // 3inst, any width
    tf_exl3::grouped_body<0, 8, 4, GROUPED_LOAD>(a, blockIdx.x, blockIdx.y, blockIdx.z);
}

extern "C" __global__ void tf_exl3_grouped_1(tf_exl3::GroupedArgs a) {  // mcg, any width
    tf_exl3::grouped_body<1, 8, 4, GROUPED_LOAD>(a, blockIdx.x, blockIdx.y, blockIdx.z);
}

// mcg at 4 tiles a block: twice the blocks of tf_exl3_grouped_1 on the same k slices, each column's sum in the same warp
// order, so the same bits (decode windows pick it where it measures faster: cuda/exl3_experts.zig ntFor).
extern "C" __global__ void tf_exl3_grouped_1_nt4(tf_exl3::GroupedArgs a) {
    tf_exl3::grouped_body<1, 4, 4, GROUPED_LOAD>(a, blockIdx.x, blockIdx.y, blockIdx.z);
}

// port note (af9777b49): the fork's SHFL decode variants — 4-bit mcg decode windows with every trellis word read once
// (warp_tiles_shfl, sm_120 up; main's loop below): the same k slices, MMA chains and warp-order sums, so the bits of
// tf_exl3_grouped_1_k8r8 (<= 8 rows) and _nt4 (9 to 32 rows).
#if __CUDA_ARCH__ >= 1200
constexpr int GROUPED_SHFL = tf_exl3::SHFL;
#else
constexpr int GROUPED_SHFL = tf_exl3::PLAIN;
#endif
extern "C" __global__ void tf_exl3_grouped_1_k8r8s(tf_exl3::GroupedArgs a) {
    tf_exl3::grouped_body_v2<1, 4, 4, GROUPED_SHFL, 8, 8>(a, blockIdx.x, blockIdx.y, blockIdx.z);
}
extern "C" __global__ void tf_exl3_grouped_1_k8r16s(tf_exl3::GroupedArgs a) {
    tf_exl3::grouped_body_v2<1, 4, 4, GROUPED_SHFL, 8, 16>(a, blockIdx.x, blockIdx.y, blockIdx.z);
}

